import traceback
from typing import Optional, List

from taf.ul.sbts.energy_saving.interface import energy_saving

from taf.rfrl.csv4all.resources.utilities.utilities import test_logger
from taf.rfrl.csv4all.resources.energy_saving.exceptions import SetupEnergySavingFailed


class EnergySaving:
    def __init__(self, admin_alias: str):
        self.energy_saving_groups = None
        self.nr_cells_in_groups = []
        self.lte_cells_in_groups = []
        self.lte_power_groups = None
        self.nr_power_groups = None
        self.admin_alias = admin_alias
        self.energy_saving = energy_saving(default_alias=self.admin_alias)

    def backup_and_load_scf(self) -> str:
        return self.energy_saving.backup_and_load_scf(connection=self.admin_alias)

    def setup_energy_saving_groups(self, force_recreate_groups: bool = True):
        try:
            powergroups = self.energy_saving.setup_complete_energy_saving(force_recreate_groups=force_recreate_groups,
                                                                           xml_scf=self.backup_and_load_scf())
            test_logger(f"Power groups: {powergroups}", "DEBUG")

            if powergroups["errors"]:
                test_logger(f"Setup failed", "ERROR")
                raise Exception(f"Power Groups not created")

            self.nr_power_groups = list(powergroups["nrpgrp_dns"])
            test_logger(f"NR power groups: {self.nr_power_groups}")
            self.lte_power_groups = list(powergroups["psgrp_dns"])
            test_logger(f"LTE power groups: {self.lte_power_groups}")
            self.energy_saving_groups = self.nr_power_groups + self.lte_power_groups
            self.nr_cells_in_groups = []
            for nr_group_cells in powergroups["nrpgrp_dns"].values():
                self.nr_cells_in_groups.extend(nr_group_cells)
            self.lte_cells_in_groups = []
            for lte_group_cells in powergroups["psgrp_dns"].values():
                self.lte_cells_in_groups.extend(lte_group_cells)

        except Exception as e:
            test_logger(traceback.format_exc(), "DEBUG")
            raise SetupEnergySavingFailed(e)

    def enable_energy_saving_groups(self):
        self.energy_saving.enable_energy_saving(self.nr_power_groups + self.lte_power_groups,
                                                connection=self.admin_alias)
        test_logger("Energy saving enabled for all groups")
        self.wait_on_cells()

    def wait_on_cells(self):
        for rat in ['lte', 'nr']:
            test_logger(f"Waiting on {rat.upper()} cells")
            power_groups = self.nr_power_groups if rat == 'nr' else self.lte_power_groups
            if not power_groups:
                continue
            try:
                allowed_missing_cells = self.energy_saving.get_allowed_missing_cells_count(rat,
                                                                                           self.backup_and_load_scf(),
                                                                                           power_groups)
                test_logger(f"{rat.upper()} allowed missing cells: {allowed_missing_cells}", "DEBUG")
            except Exception as e:
                test_logger(e, "ERROR")
                allowed_missing_cells = 0
            cell_ids = self.nr_cells_in_groups if rat == "nr" else self.lte_cells_in_groups
            self.wait_until_all_cells_in_energy_saving(rat, cell_ids=cell_ids, allowed_missing=allowed_missing_cells)
            test_logger(f"All {rat.upper()} cells are in energy saving state")

    def wait_until_all_cells_in_energy_saving(self, rat_cell: str, cell_ids: Optional[List[int]] = None,
                                              allowed_missing: int = 0):
        test_logger("Waiting until energy saving will be active")
        if self.energy_saving.wait_until_all_cells_in_energy_saving(cell_type=rat_cell, cell_ids=cell_ids,
                                                                    allowed_missing=allowed_missing,
                                                                    timeout=3600, connection=self.admin_alias):
            test_logger(f"Setup energy saving completed for {rat_cell.upper()} cells")
        else:
            raise SetupEnergySavingFailed("Waiting on cells in energy saving state has timed out")

    def disable_energy_saving(self):
        self.energy_saving.disable_energy_saving(self.energy_saving_groups, connection=self.admin_alias)
